import{_ as r,o as t,c as e,a2 as l}from"./chunks/framework.mRCPFc5l.js";const g=JSON.parse('{"title":"牛族","description":"","frontmatter":{},"headers":[],"relativePath":"表层/种族/牛族.md","filePath":"表层/种族/牛族.md","lastUpdated":1787065118000}'),o={name:"表层/种族/牛族.md"};function i(n,a,s,h,d,u){return t(),e("div",null,[...a[0]||(a[0]=[l('<h1 id="牛族" tabindex="-1">牛族 <a class="header-anchor" href="#牛族" aria-label="Permalink to &quot;牛族&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>牛族是五大主族之一，共同体时期承担农业相关的一切，以<strong>耐心与求稳</strong>为种族核心特质。黑暗时代中，牛族成为<strong>首个彻底沦为奴隶的种族</strong>，曾试图抵抗新五族的压迫，但被法师以绝对力量镇压至近乎灭绝，剩余族人彻底丧失主权，成为流亡种族。当前牛族隐居，族群规模极小，与兔族、鹤族联系紧密。</p><hr><h2 id="体貌特征" tabindex="-1">体貌特征 <a class="header-anchor" href="#体貌特征" aria-label="Permalink to &quot;体貌特征&quot;">​</a></h2><ul><li><strong>形态</strong>：直立行走，具有牛类动物的典型福瑞形态。</li><li><strong>体格</strong>：体型高大强壮，力量强大，适合重体力劳动。</li><li><strong>角</strong>：头部生有明显的牛角，形态多样。</li><li><strong>毛色</strong>：以黑色、棕色、白色为主，常见黑白相间花色。</li></ul><hr><h2 id="种族特质" tabindex="-1">种族特质 <a class="header-anchor" href="#种族特质" aria-label="Permalink to &quot;种族特质&quot;">​</a></h2><h3 id="核心特质-耐心与求稳" tabindex="-1">核心特质：耐心与求稳 <a class="header-anchor" href="#核心特质-耐心与求稳" aria-label="Permalink to &quot;核心特质：耐心与求稳&quot;">​</a></h3><ul><li><strong>耐心</strong>：天生具备极强的耐心，适应农业长周期、慢回报的特点，不急于求成。</li><li><strong>求稳</strong>：倾向稳妥路线，厌恶冒险，注重安定与安全。</li><li><strong>务实</strong>：崇尚踏实的劳动，相信劳动创造价值，注重实际成果。</li><li><strong>忠诚</strong>：对共同体与同伴忠诚，集体归属感强。</li></ul><hr><h2 id="历史" tabindex="-1">历史 <a class="header-anchor" href="#历史" aria-label="Permalink to &quot;历史&quot;">​</a></h2><h3 id="共同体时期-农业担当" tabindex="-1">共同体时期：农业担当 <a class="header-anchor" href="#共同体时期-农业担当" aria-label="Permalink to &quot;共同体时期：农业担当&quot;">​</a></h3><p>在五大主族分工的共同体体系中，牛族承担<strong>农业相关的一切</strong>：</p><ul><li>负责共同体时期的粮食、蔬菜、水果等农作物生产。</li><li>管理家畜养殖，提供肉、奶、毛等动物产品。</li><li>负责共同体的粮食储备与分配管理。</li><li>在共同体五星旗帜上，牛族占据一角。</li></ul><h3 id="黑暗时代-首个沦为奴隶的种族" tabindex="-1">黑暗时代：首个沦为奴隶的种族 <a class="header-anchor" href="#黑暗时代-首个沦为奴隶的种族" aria-label="Permalink to &quot;黑暗时代：首个沦为奴隶的种族&quot;">​</a></h3><p>奴隶制在黑暗时代渐渐形成后，牛族成为<strong>第一个彻底沦为奴隶的种族</strong>。其农业生产能力被新五族视为重要的劳役资源，数百年务农积累的温顺与服从性格也成为被奴役的诱因。</p><p>沦为奴隶后，牛族曾<strong>试图抵抗新五族的压迫</strong>。然而该抵抗运动被法师以绝对力量迅速镇压，以暴力方式被镇压至<strong>近乎灭绝</strong>。</p><h3 id="后果-流亡" tabindex="-1">后果：流亡 <a class="header-anchor" href="#后果-流亡" aria-label="Permalink to &quot;后果：流亡&quot;">​</a></h3><p>剩余牛族族人彻底丧失主权，成为<strong>流亡种族</strong>，流浪于大陆各处，再未重新建立独立政权。牛族被列入&quot;流亡/丧失主权的种族&quot;之列。</p><hr><h2 id="现状" tabindex="-1">现状 <a class="header-anchor" href="#现状" aria-label="Permalink to &quot;现状&quot;">​</a></h2><p>当前牛族为<strong>隐居族群</strong>，族群规模极小，不再参与大陆政治事务。牛族与兔族、鹤族联系紧密，在兔族的深林避难所中形成了相对独立的隐居社区。</p><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./五大主族总览">五大主族总览</a></li><li><a href="./../历史/共同体时期">共同体时期</a></li><li><a href="./../历史/黑暗时代">黑暗时代</a></li><li><a href="./兔族">兔族</a></li><li><a href="./鹤族">鹤族</a></li><li><a href="./../../中层/历史/正传历史" class="layer-link" data-layer="中层">正传历史</a></li></ul><hr>',27)])])}const f=r(o,[["render",i]]);export{g as __pageData,f as default};
